#include "helpers.hpp"
void asynchronous(int corrupt,bool enabled,int delay){auto f=configured(enabled);f.through(399);Stats st;int count=0;for(int i=400;i<=1000;++i){I now=T0+i*DT;double s=(i-400)*.25;Pose2 good={{{150+s,0,0}},{{1,0,0}}};for(int ch=0;ch<2;++ch){int epoch=i-((ch==corrupt)?0:delay);if(epoch>=400&&(epoch-400)%2==0){double es=(epoch-400)*.25;Pose2 truth={{{150+es,0,0}},{{1,0,0}}};require(f.pipe.fix(ch,T0+epoch*DT,now,obs(ch==corrupt?fake(es):truth,ch)),"async fix");++count;}}auto o=f.tick(i);st.addout(i,o,good.p);if(i==500||i==700||i==1000)std::cout<<"async corrupt="<<corrupt<<" enabled="<<enabled<<" delay="<<delay<<" tick="<<i<<" error="<<norm(sub(o.position,good.p))<<" flags="<<o.flags<<" accepted="<<o.gnss_accepted<<" rejected="<<o.gnss_rejected<<" input_count="<<count<<"\n";}std::cout<<"SUMMARY async corrupt="<<corrupt<<" enabled="<<enabled<<" delay="<<delay<<" maxerr="<<st.maxerr<<" first="<<st.first<<" last="<<st.last<<" finalerr="<<norm(sub(st.prev.position,Vec3{{300,0,0}}))<<" maxjump="<<st.maxjump<<"\n";}
void true_async(bool enabled,int delay){auto f=configured(enabled);f.through(399);Stats st;for(int i=400;i<=1040;++i){I now=T0+i*DT;double s=(i-400)*.25;for(int ch=0;ch<2;++ch){int epoch=i-(ch?delay:0);if(epoch>=400&&(epoch-400)%2==0)require(f.pipe.fix(ch,T0+epoch*DT,now,obs(returning((epoch-400)*.25),ch)),"true async fix");}auto o=f.tick(i);st.addout(i,o,returning(s).p);}std::cout<<"SUMMARY true_async enabled="<<enabled<<" delay="<<delay<<" maxerr="<<st.maxerr<<" first="<<st.first<<" last="<<st.last<<" finalerr="<<norm(sub(st.prev.position,returning(160).p))<<" maxjump="<<st.maxjump<<"\n";}
Pose2 wide_return(double s){double a=PI/3,r=25.;Vec3 dir={{std::cos(a),std::sin(a),0}};if(s<=40)return {add(Vec3{{150,0,0}},mul(dir,s)),dir};Vec3 start=add(Vec3{{150,0,0}},mul(dir,40));double u=s-40,arc=2*r*a;if(u<arc){double h=a-u/r;return {add(start,{{r*(std::sin(a)-std::sin(h)),r*(std::cos(h)-std::cos(a)),0}}),{{std::cos(h),std::sin(h),0}}};}Vec3 end=add(start,{{2*r*std::sin(a),0,0}});u-=arc;if(u<40)return {add(end,{{u*std::cos(a),-u*std::sin(a),0}}),{{std::cos(a),-std::sin(a),0}}};return {add(end,{{40*std::cos(a)+(u-40),-end[1],0}}),{{1,0,0}}};}
void phase_return(bool enabled){auto f=configured(enabled);f.through(399);Stats st;for(int i=400;i<=1280;++i){I now=T0+i*DT;double s=(i-400)*.25;auto p=wide_return(s);if(i%2==0)for(int ch=0;ch<2;++ch)require(f.pipe.fix(ch,now,now,obs(p,ch)),"wide return fix");auto o=f.tick(i);st.addout(i,o,p.p);if(i==1000||i==1200||i==1280)std::cout<<"phase_return enabled="<<enabled<<" tick="<<i<<" flags="<<o.flags<<" error="<<norm(sub(o.position,p.p))<<" route_s="<<o.route_s<<" truth_map_x="<<p.p[0]<<" accepted="<<o.gnss_accepted<<" rejected="<<o.gnss_rejected<<"\n";}std::cout<<"SUMMARY phase_return enabled="<<enabled<<" maxerr="<<st.maxerr<<" first="<<st.first<<" last="<<st.last<<" finalerr="<<norm(sub(st.prev.position,wide_return(220).p))<<"\n";}
int main(){std::cout<<std::setprecision(17);for(int bad:{0,1})for(bool enabled:{false,true}){asynchronous(bad,enabled,0);asynchronous(bad,enabled,2);}for(bool enabled:{false,true}){for(int delay:{0,1,2})true_async(enabled,delay);phase_return(enabled);}}

